/* eslint-env jest */
'use strict';

const os = require('os');
const opentelemetry = require('@opentelemetry/api');

const yandexLogger = require('../../src');

jest.mock('@opentelemetry/api', () => {
    return Object.assign(
        { __esModule: true },
        jest.requireActual('@opentelemetry/api'),
        { isSpanContextValid: jest.fn().mockReturnValue(true) }
    );
});

describe('YandexLogger. Middleware. Tracing', () => {
    const { context, trace } = require('@opentelemetry/api');

    const tracer = trace.getTracer('yandex-logger/tests');
    const { AsyncHooksContextManager } = require('@opentelemetry/context-async-hooks');

    let logger;
    let stream;
    let baseRecord;
    let jestFakeTimers;

    beforeAll(() => {
        const contextManager = new AsyncHooksContextManager();
        contextManager.enable();
        context.setGlobalContextManager(contextManager);
    });

    beforeEach(() => {
        // Initialize a mock function to replace `write`.
        stream = { write: jest.fn() };

        logger = yandexLogger({
            streams: [
                { stream },
            ],
            middleware: [
                require('../../middleware/tracing')(),
            ],
        });

        baseRecord = {
            pid: process.pid,
            date: expect.any(Date),
            name: 'yandex-logger',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            msg: 'message',
            msgFormat: 'message',
            msgArgs: [],
        };

        // Use fake timers and set the system time
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        jestFakeTimers.clearAllTimers();
    });

    it('должен взять traceId и spanId из opentelemetry', () => {
        let req = { id: 'req-1' };

        tracer.startActiveSpan('test', span => {
            span.setStatus({ code: opentelemetry.SpanStatusCode.OK });
            logger.info({ req }, 'message');
            span.end();
        });

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req,
            traceId: expect.any(String),
            spanId: expect.any(String),
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен падать без traceId и spanId', () => {
        let req = {};
        logger.info({ req }, 'message');

        expect(stream.write).toHaveBeenCalledWith({
            ...baseRecord,
            req,
            requestId: undefined,
        });
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('не должен падать без record.req', () => {
        logger.info('message');

        expect(stream.write).toHaveBeenCalledWith(baseRecord);
        expect(stream.write).toHaveBeenCalledTimes(1);
    });
});
